public class ValuesController : ControllerBase
{
    public readonly IKeyedServiceProvider keyedServiceProvider;

    public ValuesController(IKeyedServiceProvider _keyedServiceProvider)
    {
        keyedServiceProvider = _keyedServiceProvider;
    }
   
    [HttpGet("permanent")]
    public ActionResult GetEmployee()
    {
        var ss = keyedServiceProvider.GetRequiredKeyedService<IEmployee>("tempEmployee");
        return Ok(ss.GetMessage());
    }
}
